package com.smartcanteen.api;
import com.smartcanteen.domain.User; import com.smartcanteen.repo.UserRepository; import io.jsonwebtoken.*; import javax.crypto.SecretKey; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final UserRepository users; final PasswordEncoder encoder; final SecretKey key; AuthController(UserRepository u,PasswordEncoder e,SecretKey k){users=u;encoder=e;key=k;} record Credentials(@Email String email,@NotBlank String password){} record Registration(@Email String email,@NotBlank String name,@NotBlank String password){} @PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody Registration r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.status(HttpStatus.CONFLICT).body("Email already registered");User u=new User(r.email(),r.name(),encoder.encode(r.password()),User.Role.STUDENT);users.save(u);return ResponseEntity.ok(view(u));} @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody Credentials c){var found=users.findByEmail(c.email());if(found.isEmpty()||!encoder.matches(c.password(),found.get().password))return ResponseEntity.status(401).build();User u=found.get();return ResponseEntity.ok(java.util.Map.of("token",token(u),"user",view(u)));} String token(User u){return Jwts.builder().subject(u.email).claim("role",u.role.toString()).issuedAt(new java.util.Date()).expiration(new java.util.Date(System.currentTimeMillis()+86400000)).signWith(key).compact();} java.util.Map<String,Object> view(User u){return java.util.Map.of("id",u.id,"email",u.email,"name",u.name,"role",u.role.toString());} }
